package dev.homecontrol.app;

import org.json.*;
import java.util.*;

/** Schema-driven controls and per-property state, never synthetic default values. */
final class MijiaModel {
    static JSONObject parse(JSONObject spec)throws JSONException{
        JSONArray properties=new JSONArray(),actions=new JSONArray(),services=spec.optJSONArray("services");JSONObject translations=spec.optJSONObject("_translations"),zh=translations==null?null:translations.optJSONObject("zh_cn");if(zh==null&&translations!=null)zh=translations.optJSONObject("zh_CN");
        if(services!=null)for(int i=0;i<services.length();i++){JSONObject service=services.optJSONObject(i);if(service==null||"device-information".equals(type(service.optString("type"))))continue;int siid=service.optInt("iid");if(siid<=0)continue;String serviceKey=String.format(Locale.ROOT,"service:%03d",siid),serviceName=label(zh,serviceKey,service);
            LinkedHashMap<Integer,JSONObject> definitions=new LinkedHashMap<>();JSONArray props=service.optJSONArray("properties");if(props!=null)for(int j=0;j<props.length();j++){JSONObject p=props.optJSONObject(j);if(p==null||p.optInt("iid")<=0)continue;String name=type(p.optString("type"));if(name.contains("password")||name.contains("secret")||name.contains("token"))continue;int piid=p.getInt("iid");String key=serviceKey+String.format(Locale.ROOT,":property:%03d",piid);JSONArray choices=new JSONArray(),raw=p.optJSONArray("value-list");if(raw!=null)for(int n=0;n<raw.length();n++){JSONObject value=raw.optJSONObject(n);if(value!=null&&value.has("value"))choices.put(new JSONObject().put("value",value.get("value")).put("description",zh!=null?zh.optString(key+String.format(Locale.ROOT,":valuelist:%03d",n),translate(value.optString("description"))):translate(value.optString("description"))));}
                JSONObject cap=new JSONObject().put("key","p:"+siid+":"+piid).put("siid",siid).put("piid",piid).put("name",name).put("title",label(zh,key,p)).put("service",serviceName).put("format",p.optString("format")).put("unit",p.optString("unit")).put("readable",access(p,"read")).put("writable",access(p,"write")).put("choices",choices);if(p.optJSONArray("value-range")!=null)cap.put("range",p.getJSONArray("value-range"));definitions.put(piid,cap);if(cap.getBoolean("readable")||cap.getBoolean("writable"))properties.put(cap);
            }
            JSONArray acts=service.optJSONArray("actions");if(acts!=null)for(int j=0;j<acts.length();j++){JSONObject a=acts.optJSONObject(j);if(a==null||a.optInt("iid")<=0)continue;JSONArray in=a.optJSONArray("in"),inputs=new JSONArray();boolean supported=in==null||in.length()<=8;if(in!=null)for(int n=0;n<in.length();n++){JSONObject prop=definitions.get(in.optInt(n));if(prop==null){supported=false;break;}inputs.put(new JSONObject(prop.toString()));}String actionName=type(a.optString("type"));if(Arrays.asList("factory-reset","format","delete","reset").contains(actionName))continue;int aiid=a.getInt("iid");actions.put(new JSONObject().put("key","a:"+siid+":"+aiid).put("siid",siid).put("aiid",aiid).put("name",actionName).put("title",label(zh,serviceKey+String.format(Locale.ROOT,":action:%03d",aiid),a)).put("service",serviceName).put("inputs",inputs).put("supported",supported));}
        }
        return new JSONObject().put("capabilities",properties).put("actions",actions).put("specType",spec.optString("type"));
    }
    static JSONArray retain(JSONArray next,JSONArray previous)throws JSONException{Map<String,JSONObject> old=map(previous);for(int i=0;i<next.length();i++){JSONObject p=next.getJSONObject(i),before=old.get(p.optString("key"));if(before!=null&&before.has("value")&&p.optString("format").equals(before.optString("format"))){p.put("value",before.get("value")).put("valueTime",before.optLong("valueTime")).put("stale",true);}}return next;}
    static void results(JSONArray properties,JSONArray results,String did,long now)throws JSONException{Map<String,JSONObject> byKey=map(properties);if(results==null)return;for(int i=0;i<results.length();i++){JSONObject r=results.optJSONObject(i);if(r==null||!did.equals(r.optString("did")))continue;JSONObject p=byKey.get("p:"+r.optInt("siid")+":"+r.optInt("piid"));if(p==null)continue;int code=r.optInt("code",Integer.MIN_VALUE);p.put("readCode",code);if(code==0&&r.has("value")&&!r.isNull("value"))p.put("value",r.get("value")).put("valueTime",now).put("stale",false);}}
    static boolean valid(JSONObject p,Object value){List<Object> options=new ArrayList<>();List<Number> range=new ArrayList<>();JSONArray choices=p.optJSONArray("choices"),bounds=p.optJSONArray("range");if(choices!=null)for(int i=0;i<choices.length();i++){JSONObject c=choices.optJSONObject(i);if(c!=null)options.add(c.opt("value"));}if(bounds!=null){if(bounds.length()!=3)return false;for(int i=0;i<3;i++){Object n=bounds.opt(i);if(!(n instanceof Number))return false;range.add((Number)n);}}return MijiaValue.allowed(p.optString("format"),value,options,range);}
    static boolean color(JSONObject p){return "color".equals(p.optString("name"))&&"uint32".equals(p.optString("format"));}
    static String display(JSONObject p){if(!p.has("value")||p.isNull("value"))return p.optBoolean("writable")&&!p.optBoolean("readable")?"点击设置":"状态待更新";Object value=p.opt("value");if(color(p)&&value instanceof Number)return String.format(Locale.ROOT,"#%06X",((Number)value).longValue()&0xffffff);JSONArray choices=p.optJSONArray("choices");if(choices!=null)for(int i=0;i<choices.length();i++){JSONObject c=choices.optJSONObject(i);if(c!=null&&MijiaValue.equivalent(value,c.opt("value")))return c.optString("description",String.valueOf(value));}if(value instanceof Boolean)return (Boolean)value?"开":"关";String unit=p.optString("unit"),suffix="percentage".equals(unit)?"%":"celsius".equals(unit)?"℃":"kelvin".equals(unit)?" K":"seconds".equals(unit)?" 秒":"minutes".equals(unit)?" 分钟":"";return String.valueOf(value)+suffix;}
    static JSONObject find(JSONArray list,String key){if(list!=null)for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(p!=null&&key.equals(p.optString("key")))return p;}return null;}
    private static Map<String,JSONObject> map(JSONArray list){Map<String,JSONObject> out=new HashMap<>();if(list!=null)for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(p!=null)out.put(p.optString("key"),p);}return out;}
    private static boolean access(JSONObject p,String name){JSONArray access=p.optJSONArray("access");if(access!=null)for(int i=0;i<access.length();i++)if(name.equals(access.optString(i)))return true;return false;}
    private static String label(JSONObject zh,String key,JSONObject d){String value=zh==null?"":zh.optString(key);if(value.isEmpty()){String name=type(d.optString("type")),translated=translate(name);value=!translated.equals(name)?translated:translate(d.optString("description",name));}return value;}
    static String type(String urn){String[] parts=urn.split(":");return parts.length>3?parts[3]:urn;}
    private static String translate(String value){String[] en={"on","light","fan","air-conditioner","outlet","switch","mode","brightness","color-temperature","temperature","target-temperature","relative-humidity","battery-level","speed-level","fan-level","volume","status","fault","start","stop","pause","toggle","Day","Night","day","night","fan-speed","air-purifier","air-fresh","robot-cleaner","door-state","lock","child-lock","heater","water-heater","curtain","position","target-position","pm2.5-density","filter-life-level","power-consumption","energy-consumption"};String[] cn={"电源","灯光","风扇","空调","插座","开关","模式","亮度","色温","温度","目标温度","湿度","电量","速度档位","风速","音量","状态","故障","启动","停止","暂停","切换开关","日光","夜灯","日光","夜灯","风速","空气净化器","新风","扫地机器人","门状态","门锁","童锁","加热器","热水器","窗帘","位置","目标位置","PM2.5","滤芯寿命","功率","耗电量"};for(int i=0;i<en.length;i++)if(en[i].equals(value))return cn[i];return value;}
    private MijiaModel(){}
}
